head.b:skin:
/*!
 * Theme Name: Maison Édit
 * Description: An editorial, magazine-style fashion blog theme — polished, image-forward, and effortless to read.
 * Author: Jules
 */

/* ==========================================================================
   CSS Variables
   ========================================================================== */
:root {
  /* Colors */
  --bg-color: #FAF7F2;
  --text-primary: #2B2B2B;
  --text-secondary: #5c5c5c;
  --accent-primary: #B76E56;
  --accent-primary-hover: #9c5c47;
  --accent-secondary: #8A9A8E;
  --border-color: #E4DDD2;
  --card-bg: #FFFFFF;

  /* Typography */
  --font-heading: 'Playfair Display', serif;
  --font-body: 'Inter', sans-serif;

  /* Fluid Typography (clamp values for scaling between mobile and desktop) */
  --text-base: clamp(1rem, 0.95rem + 0.25vw, 1.125rem); /* 16px to 18px */
  --text-sm: clamp(0.875rem, 0.85rem + 0.125vw, 0.9375rem); /* 14px to 15px */

  --h1-size: clamp(2.25rem, 1.8rem + 2.25vw, 3.375rem); /* 36px to 54px */
  --h2-size: clamp(1.75rem, 1.5rem + 1.25vw, 2.375rem); /* 28px to 38px */
  --h3-size: clamp(1.375rem, 1.2rem + 0.875vw, 1.8125rem); /* 22px to 29px */
  --h4-size: clamp(1.125rem, 1rem + 0.625vw, 1.4375rem); /* 18px to 23px */

  /* Spacing */
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 2rem;
  --space-lg: 4rem;
  --space-xl: 6rem;

  /* UI Details */
  --border-radius: 6px;
  --transition: all 0.3s ease;
  --max-width: 1200px;
  --content-width: 760px;
}

/* ==========================================================================
   Base Styles & Reset
   ========================================================================== */
*, *::before, *::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  background-color: var(--bg-color);
  color: var(--text-primary);
  font-family: var(--font-body);
  font-size: var(--text-base);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: var(--accent-primary);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  color: var(--accent-primary-hover);
}

/* ==========================================================================
   Typography
   ========================================================================== */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 400;
  line-height: 1.2;
  margin-top: 0;
  margin-bottom: var(--space-sm);
  color: var(--text-primary);
}

h1 { font-size: var(--h1-size); }
h2 { font-size: var(--h2-size); }
h3 { font-size: var(--h3-size); }
h4 { font-size: var(--h4-size); }

p {
  margin-top: 0;
  margin-bottom: var(--space-sm);
}

/* ==========================================================================
   Accessibility
   ========================================================================== */
/* Keyboard focus state */
:focus-visible {
  outline: 2px solid var(--accent-primary);
  outline-offset: 2px;
}

/* Skip link for screen readers */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--accent-primary);
  color: white;
  padding: 8px;
  z-index: 100;
  transition: top 0.2s;
}

.skip-link:focus {
  top: 0;
}

/* Screen reader only utility class */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* ==========================================================================
   Layout Scaffolding
   ========================================================================== */
.page-wrapper {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

main {
  flex: 1;
}

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-sm);
}

.content-container {
  width: 100%;
  max-width: var(--content-width);
  margin: 0 auto;
}

/* ==========================================================================
   Header & Navigation
   ========================================================================== */
.site-header {
  background-color: var(--bg-color);
  border-bottom: 1px solid var(--border-color);
  position: relative;
  z-index: 50;
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) 0;
  height: 80px;
}

/* Logo */
.site-logo {
  font-family: var(--font-heading);
  font-size: var(--h3-size);
  font-weight: 600;
  color: var(--text-primary);
  text-decoration: none;
  letter-spacing: -0.02em;
}

.site-logo:hover {
  color: var(--accent-primary);
}

/* Mobile Toggle */
.nav-toggle {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  width: 30px;
  height: 20px;
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 0;
  z-index: 60;
  min-height: 44px;
  min-width: 44px;
  align-items: center;
}

.nav-toggle span {
  display: block;
  width: 30px;
  height: 2px;
  background-color: var(--text-primary);
  transition: var(--transition);
  border-radius: 2px;
}

.nav-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(9px) rotate(45deg);
}
.nav-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}
.nav-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-9px) rotate(-45deg);
}

/* Navigation Menu */
.site-nav {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background-color: var(--bg-color);
  border-bottom: 1px solid var(--border-color);
  padding: var(--space-md);
  display: none;
  flex-direction: column;
  gap: var(--space-sm);
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
}

.site-nav.is-open {
  display: flex;
}

.site-nav a {
  color: var(--text-primary);
  font-size: var(--text-base);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: var(--space-xs) 0;
}

.site-nav a:hover {
  color: var(--accent-primary);
}

/* Search Box */
.header-search {
  margin-top: var(--space-sm);
  position: relative;
}

.header-search input[type="text"] {
  width: 100%;
  padding: 10px 40px 10px 15px;
  border: 1px solid var(--border-color);
  border-radius: 20px;
  background-color: var(--card-bg);
  font-family: var(--font-body);
  font-size: var(--text-sm);
  color: var(--text-primary);
}

.header-search input[type="text"]:focus {
  outline: none;
  border-color: var(--accent-primary);
}

.header-search button {
  position: absolute;
  right: 5px;
  top: 50%;
  transform: translateY(-50%);
  background: transparent;
  border: none;
  cursor: pointer;
  padding: 5px 10px;
  color: var(--text-secondary);
  min-height: 44px;
  min-width: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.header-search button:hover {
  color: var(--accent-primary);
}

@media (min-width: 768px) {
  .nav-toggle {
    display: none;
  }

  .site-nav {
    position: static;
    display: flex;
    flex-direction: row;
    align-items: center;
    border-bottom: none;
    padding: 0;
    box-shadow: none;
    gap: var(--space-md);
  }

  .header-search {
    margin-top: 0;
    width: 250px;
  }
}

/* ==========================================================================
   Homepage Feed & Archive Layout
   ========================================================================== */
.main-feed {
  padding: var(--space-md) 0 var(--space-lg);
}

/* Post Grid */
.post-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
}

@media (min-width: 600px) {
  .post-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 900px) {
  .post-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: var(--space-lg) var(--space-md);
  }
}

/* Post Card */
.post-card {
  display: flex;
  flex-direction: column;
}

.post-card-image-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 3/4; /* Editorial portrait ratio */
  background-color: var(--border-color);
  margin-bottom: var(--space-sm);
  overflow: hidden;
  border-radius: 4px;
}

.post-card-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}

.post-card:hover .post-card-image {
  transform: scale(1.03);
}

.post-card-meta {
  font-size: var(--text-sm);
  color: var(--accent-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-xs);
  display: flex;
  gap: 10px;
}

.post-card-title {
  font-size: var(--h4-size);
  margin-bottom: var(--space-xs);
}

.post-card-title a {
  color: var(--text-primary);
}

.post-card-title a:hover {
  color: var(--accent-primary);
}

.post-card-snippet {
  color: var(--text-secondary);
  font-size: var(--text-sm);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Hero Post (First post on homepage) */
.hero-post {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
  margin-bottom: var(--space-lg);
  border-bottom: 1px solid var(--border-color);
  padding-bottom: var(--space-lg);
}

@media (min-width: 768px) {
  .hero-post {
    grid-template-columns: 3fr 2fr;
    align-items: center;
    gap: var(--space-lg);
  }
}

.hero-post .post-card-image-wrap {
  aspect-ratio: 16/9; /* Wider ratio for hero */
}

@media (min-width: 768px) {
  .hero-post .post-card-image-wrap {
    aspect-ratio: 4/3;
  }
}

.hero-post .post-card-title {
  font-size: var(--h2-size);
}

.hero-post .post-card-snippet {
  -webkit-line-clamp: 4;
  font-size: var(--text-base);
  margin-bottom: var(--space-sm);
}

/* Pagination */
.blog-pager {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-lg);
  border-top: 1px solid var(--border-color);
  margin-top: var(--space-lg);
}

.blog-pager-older-link,
.blog-pager-newer-link {
  display: inline-block;
  padding: 10px 20px;
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius);
  color: var(--text-primary);
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-size: var(--text-sm);
  transition: var(--transition);
}

.blog-pager-older-link:hover,
.blog-pager-newer-link:hover {
  border-color: var(--accent-primary);
  color: var(--accent-primary);
}

/* ==========================================================================
   Post Page & Article Styling
   ========================================================================== */
.post-article {
  padding: var(--space-md) 0 var(--space-xl);
}

/* Breadcrumbs */
.breadcrumbs {
  font-size: var(--text-sm);
  color: var(--text-secondary);
  margin-bottom: var(--space-md);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.breadcrumbs a {
  color: var(--text-secondary);
}

.breadcrumbs a:hover {
  color: var(--accent-primary);
}

.breadcrumbs-separator {
  margin: 0 8px;
  color: var(--border-color);
}

/* Post Header */
.post-header {
  text-align: center;
  margin-bottom: var(--space-lg);
}

.post-title {
  margin-bottom: var(--space-sm);
}

.post-byline {
  font-size: var(--text-sm);
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 15px;
}

.post-byline-author {
  color: var(--text-primary);
  font-weight: 500;
}

/* Post Hero Image */
.post-hero-image {
  margin-bottom: var(--space-lg);
  border-radius: 4px;
  overflow: hidden;
}

.post-hero-image img {
  width: 100%;
  height: auto;
  aspect-ratio: 16/9;
  object-fit: cover;
}

/* Post Body Content */
.post-body {
  font-size: var(--text-base);
  line-height: 1.8;
  color: var(--text-primary);
}

.post-body h2 {
  margin-top: var(--space-lg);
  margin-bottom: var(--space-md);
  padding-bottom: var(--space-xs);
  border-bottom: 1px solid var(--border-color);
}

.post-body h3 {
  margin-top: var(--space-md);
  margin-bottom: var(--space-sm);
}

.post-body p {
  margin-bottom: var(--space-md);
}

.post-body a {
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

.post-body a:hover {
  text-decoration-thickness: 2px;
}

.post-body img {
  border-radius: 4px;
  margin: var(--space-md) auto;
}

.post-body blockquote {
  margin: var(--space-lg) 0;
  padding: 0 var(--space-md);
  border-left: 2px solid var(--accent-primary);
  font-family: var(--font-heading);
  font-size: var(--h4-size);
  font-style: italic;
  color: var(--accent-primary);
}

/* Author Bio */
.author-bio-block {
  margin-top: var(--space-xl);
  padding-top: var(--space-lg);
  border-top: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  align-items: center;
  text-align: center;
}

@media (min-width: 600px) {
  .author-bio-block {
    flex-direction: row;
    text-align: left;
    align-items: flex-start;
  }
}

.author-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  object-fit: cover;
}

.author-info h3 {
  font-size: var(--h4-size);
  margin-bottom: var(--space-xs);
}

.author-desc {
  color: var(--text-secondary);
  font-size: var(--text-sm);
  margin: 0;
}

/* Related Posts & TOC */
.related-posts {
  margin-top: var(--space-xl);
  padding-top: var(--space-lg);
  border-top: 1px solid var(--border-color);
}

.related-posts-title {
  font-size: var(--h3-size);
  margin-bottom: var(--space-md);
}

.toc-container {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  padding: var(--space-md);
  margin: var(--space-md) 0;
  border-radius: var(--border-radius);
}

.toc-title {
  font-size: var(--text-base);
  font-family: var(--font-heading);
  margin-bottom: var(--space-sm);
  font-weight: 600;
}

.toc-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.toc-list li {
  margin-bottom: var(--space-xs);
}

.toc-list a {
  color: var(--text-secondary);
  font-size: var(--text-sm);
  text-decoration: none;
}

.toc-list a:hover {
  color: var(--accent-primary);
  text-decoration: underline;
}

/* ==========================================================================
   Footer
   ========================================================================== */
.site-footer {
  background-color: var(--card-bg);
  border-top: 1px solid var(--border-color);
  padding: var(--space-lg) 0;
  margin-top: auto;
}

.footer-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: var(--space-md);
}

.footer-credit {
  font-size: var(--text-sm);
  color: var(--text-secondary);
}

.footer-nav {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--space-sm);
}

.footer-nav a {
  font-size: var(--text-sm);
  color: var(--text-secondary);
}

.footer-nav a:hover {
  color: var(--accent-primary);
}

/* ==========================================================================
   Archive & Error Pages
   ========================================================================== */
.archive-header {
  text-align: center;
  padding: var(--space-lg) 0;
  border-bottom: 1px solid var(--border-color);
  margin-bottom: var(--space-lg);
}

.archive-header h1 {
  font-size: var(--h2-size);
  margin-bottom: var(--space-xs);
  text-transform: capitalize;
}

.archive-header p {
  color: var(--text-secondary);
  margin: 0;
}

.error-page {
  text-align: center;
  padding: var(--space-xl) 0;
}

.error-page h1 {
  font-size: 6rem;
  margin-bottom: 0;
  color: var(--accent-primary);
}

.error-page h2 {
  font-size: var(--h3-size);
  margin-bottom: var(--space-md);
}

.error-search {
  max-width: 400px;
  margin: var(--space-md) auto;
  position: relative;
}

.error-search input[type="text"] {
  width: 100%;
  padding: 12px 20px;
  border: 1px solid var(--border-color);
  border-radius: 25px;
  font-family: var(--font-body);
  font-size: var(--text-base);
}

.error-search input[type="text"]:focus {
  outline: none;
  border-color: var(--accent-primary);
}

/* ==========================================================================
   Product Card Component (Copy/Paste HTML Snippet Styling)
   ========================================================================== */
.me-product-card {
  display: flex;
  flex-direction: column;
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius);
  overflow: hidden;
  margin: var(--space-md) auto;
  max-width: 600px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.03);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.me-product-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(0,0,0,0.06);
}

@media (min-width: 600px) {
  .me-product-card {
    flex-direction: row;
    align-items: center;
  }
}

.me-product-image-wrap {
  width: 100%;
  aspect-ratio: 1/1;
  background-color: var(--bg-color);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: var(--space-sm);
}

@media (min-width: 600px) {
  .me-product-image-wrap {
    width: 200px;
    flex-shrink: 0;
    border-right: 1px solid var(--border-color);
  }
}

.me-product-image-wrap img {
  max-height: 100%;
  width: auto;
  object-fit: contain;
}

.me-product-info {
  padding: var(--space-md);
  display: flex;
  flex-direction: column;
  flex: 1;
}

.me-product-title {
  font-family: var(--font-heading);
  font-size: var(--h4-size);
  margin-bottom: var(--space-xs);
  color: var(--text-primary);
}

.me-product-desc {
  font-size: var(--text-sm);
  color: var(--text-secondary);
  margin-bottom: var(--space-md);
  line-height: 1.5;
}

.me-product-btn {
  display: inline-block;
  padding: 10px 20px;
  background-color: var(--text-primary);
  color: #fff !important; /* Force override post link styling */
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-size: var(--text-sm);
  font-weight: 500;
  text-align: center;
  text-decoration: none !important;
  border-radius: 4px;
  transition: background-color 0.3s ease;
  align-self: flex-start;
}

.me-product-btn:hover {
  background-color: var(--accent-primary);
}

/* ==========================================================================
   Affiliate Disclosure Snippet Styling
   ========================================================================== */
.me-affiliate-disclosure {
  font-size: 0.8rem;
  color: var(--text-secondary);
  font-style: italic;
  padding: var(--space-sm);
  background-color: rgba(228, 221, 210, 0.3); /* very light border-color */
  border-radius: 4px;
  margin: var(--space-sm) 0;
  text-align: center;
}

.me-affiliate-disclosure a {
  color: var(--text-primary);
  text-decoration: underline;
}

/* Comments Section */
.comments-section {
  margin-top: var(--space-xl);
  padding-top: var(--space-lg);
  border-top: 1px solid var(--border-color);
}

.comments-title {
  font-size: var(--h3-size);
  margin-bottom: var(--space-md);
}

/* ==========================================================================
   UI Components (Buttons, etc)
   ========================================================================== */
.btn {
  display: inline-block;
  padding: 0.75rem 1.5rem;
  background-color: var(--accent-primary);
  color: #ffffff;
  border: none;
  border-radius: var(--border-radius);
  font-family: var(--font-body);
  font-size: var(--text-sm);
  font-weight: 500;
  text-align: center;
  text-decoration: none;
  cursor: pointer;
  transition: var(--transition);
  /* Minimum tap target size */
  min-height: 44px;
}

.btn:hover {
  background-color: var(--accent-primary-hover);
  color: #ffffff;
}

body.script:
//
document.addEventListener('DOMContentLoaded', function() {
  // Mobile Navigation Toggle
  var navToggle = document.getElementById('nav-toggle');
  var siteNav = document.getElementById('site-nav');

  if (navToggle && siteNav) {
    navToggle.addEventListener('click', function() {
      var expanded = this.getAttribute('aria-expanded') === 'true' || false;
      this.setAttribute('aria-expanded', !expanded);
      siteNav.classList.toggle('is-open');
    });

    // Close menu when clicking outside
    document.addEventListener('click', function(event) {
      var isClickInside = siteNav.contains(event.target) || navToggle.contains(event.target);
      if (!isClickInside && siteNav.classList.contains('is-open')) {
        navToggle.setAttribute('aria-expanded', 'false');
        siteNav.classList.remove('is-open');
      }
    });
  }

  // Automatic Table of Contents
  var postBody = document.getElementById('post-body');
  if (postBody) {
    var headings = postBody.querySelectorAll('h2');
    if (headings.length >= 2) {
      var tocContainer = document.createElement('div');
      tocContainer.className = 'toc-container';
      tocContainer.innerHTML = '<div class="toc-title">Table of Contents</div>';

      var tocList = document.createElement('ul');
      tocList.className = 'toc-list';

      headings.forEach(function(heading, index) {
        var id = 'toc-heading-' + index;
        heading.id = id;

        var listItem = document.createElement('li');
        var link = document.createElement('a');
        link.href = '#' + id;
        link.textContent = heading.textContent;

        listItem.appendChild(link);
        tocList.appendChild(listItem);
      });

      tocContainer.appendChild(tocList);
      postBody.insertBefore(tocContainer, postBody.firstChild);
    }
  }

  // Related Posts Fetcher
  if (typeof currentPostLabel !== 'undefined' && currentPostLabel !== '') {
    var relatedContainer = document.getElementById('related-posts-container');
    if (relatedContainer) {
      var script = document.createElement('script');
      script.src = '/feeds/posts/default/-/' + encodeURIComponent(currentPostLabel) + '?alt=json-in-script&callback=renderRelatedPosts&max-results=4';
      document.body.appendChild(script);
    }
  }
});

// Related Posts Callback
function renderRelatedPosts(json) {
  var relatedContainer = document.getElementById('related-posts-container');
  if (!relatedContainer || !json.feed.entry) return;

  var html = '<div class="related-posts"><h3 class="related-posts-title">Related Posts</h3><div class="post-grid">';
  var count = 0;

  for (var i = 0; i < json.feed.entry.length; i++) {
    var entry = json.feed.entry[i];
    var url = '';
    for (var k = 0; k < entry.link.length; k++) {
      if (entry.link[k].rel === 'alternate') {
        url = entry.link[k].href;
        break;
      }
    }

    // Skip current post
    if (typeof currentPostUrl !== 'undefined' && url === currentPostUrl) continue;
    if (count >= 3) break; // Limit to 3 related posts

    var title = entry.title.$t;
    var imageUrl = '';
    if ('media$thumbnail' in entry) {
      // Upgrade Blogger's default s72-c thumbnail size to a larger image
      imageUrl = entry.media$thumbnail.url.replace(/\/s[0-9]+(\-c)?\//, '/w600-h800-c/');
    }

    html += '<article class="post-card">';
    if (imageUrl) {
       html += '<a href="' + url + '" class="post-card-image-wrap"><img src="' + imageUrl + '" alt="' + title + '" class="post-card-image" loading="lazy"/></a>';
    } else {
       html += '<a href="' + url + '" class="post-card-image-wrap"><div class="post-card-image placeholder-image"></div></a>';
    }
    html += '<div class="post-card-content"><h4 class="post-card-title"><a href="' + url + '">' + title + '</a></h4></div></article>';
    count++;
  }

  html += '</div></div>';

  if (count > 0) {
    relatedContainer.innerHTML = html;
    relatedContainer.style.display = 'block';
  }
}
